"use client";

import { useState } from "react";
import { ChannelEqPanel } from "@/components/audio-ui/devices/channel-eq/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import { useSpectrum } from "@/hooks/use-spectrum";
import {
  type ChannelEqState,
  channelEqDevice,
} from "@/components/audio-ui/devices/channel-eq/device";
import { createChannelEqEngine } from "@/components/audio-ui/devices/channel-eq/engine";

const MASTER_VOLUME = 0.7;
const MIN_HZ = 20;
const MAX_HZ = 20_000;

/**
 * A channel EQ you can plug in: its state, a panel that draws the curve it
 * plays with a handle on the mid band and an engine that plays it, each its
 * own file and none knowing the others. Play the loop and drag the handle: the
 * spectrum behind is what comes out.
 */
export function BlockChannelEq() {
  const [state, setState] = useState<ChannelEqState>(() =>
    channelEqDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  const { analyser } = useDeviceLoop({
    create: createChannelEqEngine,
    destination: master,
    state,
  });
  const spectrum = useSpectrum(analyser, { maxHz: MAX_HZ, minHz: MIN_HZ });
  return (
    <div className="rounded-4xl h-full w-full min-w-0">
      <ChannelEqPanel
        onValueChange={setState}
        spectrum={spectrum}
        value={state}
      />
    </div>
  );
}
